use strict;
use warnings;

my $candidate = "PASSWORD=8XDP5Q2RT9ZK7VB3BV4WW54\n";
my $pw = "8XDP5Q2RT9ZK7VB3BV4WW54";

my @table = (0 .. 255);
for my $n (0 .. 255) {
    my $c = $n;
    for (1 .. 8) {
        $c = ($c & 1) ? (0xEDB88320 ^ ($c >> 1)) : ($c >> 1);
    }
    $table[$n] = $c;
}

my $crc = 0xFFFFFFFF;
$crc = $table[($crc ^ ord($_)) & 0xFF] ^ ($crc >> 8) for split //, $candidate;
$crc ^= 0xFFFFFFFF;

printf "file_len=%d password_len=%d\n", length($candidate), length($pw);
printf "starts_8XD=%s ends_W54=%s charset_ok=%s\n",
    ($pw =~ /^8XD/ ? "yes" : "no"),
    ($pw =~ /W54$/ ? "yes" : "no"),
    ($pw =~ /^[A-Z0-9]+$/ ? "yes" : "no");
printf "computed_crc=%08X expected_crc=%08X match=%s\n",
    $crc, 0xB0725DC4, ($crc == 0xB0725DC4 ? "YES" : "NO");
PL

